window.NPC_CHUNK_41 = [{"name":"The Lonely Maiden","cr":8,"xp":4800,"race":"Yuki-onna","age_category":"Adult","alignment":"LE","size":"Medium","type":"undead","sub_types":["cold","incorporeal"],"init":8,"senses":["darkvision 60 ft."],"auras":["snowstorm (200 ft.)"],"ac":21,"ac_touch":21,"ac_flat_footed":16,"ac_mods":"+6 deflection, +4 Dex, +1 dodge","hp":94,"hd":"9d8+54","hd_value":9,"fort":9,"ref":7,"will":11,"defensive_abilities":["incorporeal"],"immunities":["cold","undead traits"],"weaknesses":["snow dependency","vulnerable to fire"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"2 touches +10 (4d6 cold plus chilling touch)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"chilling touch"},{"type":"fascinating gaze"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"blur"}]},{"frequency":"3/day","spells":[{"spell":"cone of cold"},{"spell":"eyebite","details":"comatose and panicked only"},{"spell":"ice storm"}]}],"dexterity":18,"intelligence":17,"wisdom":21,"charisma":22,"baseatk":6,"cmb":10,"cmd":27,"feats":[{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Spring Attack"}],"skills":[{"skill":"Bluff","value":15},{"skill":"Fly","value":12},{"skill":"Intimidate","value":18},{"skill":"Perception","value":17},{"skill":"Sense Motive","value":17},{"skill":"Spellcraft","value":15},{"skill":"Stealth","value":16},{"skill":"Survival","value":14}],"languages":["Common"],"special_abilities":[{"type":"Chilling Touch","kind":"Su","details":"A yuki-onna's touch causes 4d6 cold damage. Whenever a creature takes cold damage in this manner, it must make a DC 20 Fortitude save to avoid being staggered by the supernatural cold for 1 round. This duration stacks. The save DC is Charisma-based."},{"type":"Fascinating Gaze","kind":"Su","details":"Fascinated for 1d4 rounds, 30 feet, Will DC 20 negates. The save DC is Charisma-based."},{"type":"Snow Dependency","kind":"Ex","details":"A yuki-onna is staggered if she is ever in an area without snow while her snowstorm aura is suppressed or otherwise not functioning."},{"type":"Snowstorm","kind":"Su","details":"A yuki-onna is surrounded by whirling blasts of snow, even in areas that wouldn't allow for such weather, that comprise a 200-foot-radius spread. Within this area, the snowfall and wind gusts cause a -4 penalty on Perception checks and ranged attacks. The wind itself blows in a clockwise rotation around the yuki-onna, and functions as severe wind (Core Rulebook 439). A yuki-onna is unaffected by snowstorms or blizzards of any kind. Any effect that causes these winds to drop below severe (such as control weather or control winds) cancels the snowstorm effect entirely."}],"during_combat":"The Lonely Maiden casts ice storm on massed foes and targets individual male opponents with eyebite. In melee combat, she casts cones of cold followed by her freezing touch attacks.","morale":"The Lonely Maiden fights until destroyed, quickly melting until only a small pool of water remains.","source":"AP 51, Pathfinder RPG Bestiary 3 287"},{"name":"Kjaerulff","cr":8,"xp":4800,"race":"frost giant","gender":"Male","age_category":"venerable","classes":[{"class":"sorcerer","level":2}],"alignment":"CE","size":"Large","type":"humanoid","sub_types":["cold","giant"],"init":-3,"senses":["low-light vision"],"ac":19,"ac_touch":6,"ac_flat_footed":19,"ac_mods":"+4 armor, -3 Dex, +9 natural, -1 size","hp":86,"hd":"14d8+2d6+16","hd_value":16,"fort":10,"ref":1,"will":11,"defensive_abilities":["rock catching"],"immunities":["cold"],"weaknesses":["venerable","vulnerable to fire"],"speed":[{"type":"land","speed":40}],"melee":"greataxe +16 (3d6+9/3) or 2 slams +16 (1d8+6)","ranged":"rock +8 (1d8+9)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rock throwing","details":"120 ft."}],"spell_like_abilities_caster_level":2,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"7/day","spells":[{"spell":"cold steel","details":"1 round"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":2,"spellsknown_concentration":6,"spellsknown":[{"spell_level":1,"spell_slots":5,"spells":[{"spell":"enlarge person"},{"spell":"mage armor"},{"spell":"obscuring mist"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"detect magic"},{"spell":"light"},{"spell":"ray of frost"},{"spell":"read magic"}]}],"bloodline":"Boreal","strength":22,"dexterity":5,"constitution":12,"intelligence":17,"wisdom":19,"charisma":18,"baseatk":11,"cmb":18,"cmb_special":"+22 overrun","cmd":25,"cmd_special":"27 vs. overrun","feats":[{"feat":"Arcane Strike"},{"feat":"Blind-Fight"},{"feat":"Charge Through*"},{"feat":"Eschew Materials"},{"feat":"Greater Overrun"},{"feat":"Improved Overrun"},{"feat":"Intimidating Prowess"},{"feat":"Martial Weapon Proficiency (greataxe)"},{"feat":"Power Attack"}],"skills":[{"skill":"Bluff","value":15},{"skill":"Climb","value":15},{"skill":"Intimidate","value":29},{"skill":"Knowledge (arcana)","value":16},{"skill":"Perception","value":23},{"skill":"Spellcraft","value":16},{"skill":"Stealth","value":9,"special":"+4 in snow"}],"languages":["Common","Draconic","Erutaki","Giant","Hallit"],"special_abilities":[{"type":"Venerable","kind":"Ex","details":"Kjaerulff is of venerable age. The resulting adjustments to his ability scores decreases his CR by -2."}],"gear":"greataxe, gold-plated astrolabe (worth 500 gp), scroll of ventriloquism, wand of elemental touch* (12 charges)","before_combat":"Kjaerulff casts mage armor before confronting any strangers.","during_combat":"Kjaerulff casts obscuring mist over his opponents, then charges into combat to overrun foes with his Charge Through feat. He uses Arcane Strike and cold steel to make his axe into a +1 frost greataxe, focusing his attacks on spellcasters. If disarmed, he uses his wand of elemental touch to make cold attacks with his slams.","morale":"If reduced to fewer than 40 hit points, Kjaerulff casts enlarge person and uses Power Attack. He pursues enemies until they are in sight of the road but doesn't follow them onto it. As long as intruders are trespassing in the barrow-lands, he never surrenders, fighting to the death to protect this sacred ground.","source":"AP 51, Pathfinder RPG Bestiary 149"},{"name":"Taranaak","cr":5,"xp":1600,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"witch","level":6}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":18,"ac_touch":13,"ac_flat_footed":15,"ac_mods":"+4 armor, +2 Dex, +1 dodge, +1 natural","hp":53,"hd":"6d6+30","hd_value":6,"fort":8,"ref":7,"will":5,"speed":[{"type":"land","speed":30}],"melee":"mwk spear +6 (1d8+3/x3)","ranged":"sling +5 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hexes","details":"blight [60 feet], cauldron, evil eye [-2, 6 rounds], slumber [6 rounds]"}],"spellsprepared_caster":"witch","spellsprepared_caster_level":6,"spellsprepared_concentration":9,"spellsprepared":[{"spell_level":3,"spell_slots":3,"spells":[{"spell":"lightning bolt"},{"spell":"pain strike"},{"spell":"summon monster III"}]},{"spell_level":2,"spell_slots":4,"spells":[{"spell":"bear's endurance"},{"spell":"feast of ashes"},{"spell":"fester"},{"spell":"hold person"}]},{"spell_level":1,"spell_slots":4,"spells":[{"spell":"endure elements"},{"spell":"ill omen"},{"spell":"mage armor"},{"spell":"ray of enfeeblement"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"resistance"},{"spell":"spark"},{"spell":"touch of fatigue"}]}],"patron":"Endurance","strength":15,"dexterity":14,"constitution":16,"intelligence":16,"wisdom":8,"charisma":10,"baseatk":3,"cmb":5,"cmd":18,"feats":[{"feat":"Brew Potion"},{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Toughness"}],"skills":[{"skill":"Craft (alchemy)","value":16},{"skill":"Intimidate","value":9},{"skill":"Knowledge (arcana)","value":12},{"skill":"Knowledge (nature)","value":12},{"skill":"Perception","value":5},{"skill":"Survival","value":5}],"languages":["Common","Abyssal","Erutaki","Giant","Skald"],"sq":["witch's familiar (weasel named Ranaak [stores all prepared spells and patron spells, plus alter self, cure moderate wounds, rage, sleet storm, and additional spells of your choice])"],"gear":"sling with 10 bullets, masterwork spear, amulet of natural armor +1, cloak of resistance +1, cauldron, furs, spell component pouch, potion of cure moderate wounds, potion of rage, scroll of secure shelter","before_combat":"Before visitors arrive, Taranaak casts bear's endurance and mage armor.","during_combat":"Taranaak casts summon monster III on the first round of combat to summon a fiendish wolverine. He then supports his fellow cannibals with spells and hexes, focusing on effects that weaken or paralyze foes, such as hold person or ray of enfeeblement.","morale":"If reduced to fewer than 10 hit points, or if all of the cannibals are killed, Taranaak attempts to flee into the tundra.","base_statistics":"Without his spells, Taranaak's statistics are AC 14, touch 13, flat-footed 11; hp 41; Fort +6; Con 12.","source":"AP 51, Advanced Player's Guide 65"},{"name":"Naquun","cr":7,"xp":3200,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"ranger","level":7,"archetype":"guide"}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["chaotic","evil","human"],"templates_applied":"quasit-possessed","init":5,"init_special":"+2 in cold","ac":20,"ac_touch":16,"ac_flat_footed":14,"ac_mods":"+3 armor, +5 Dex, +1 dodge, +1 shield","hp":71,"hd":"7d10+28","hd_value":7,"hp_mods":"fast healing 2","fort":7,"ref":10,"will":4,"save_mods":"+2 vs. poison","dr":"5/cold iron","resists":["electricity 20"],"weaknesses":["spell vulnerability"],"speed":[{"type":"land","speed":30}],"melee":"+1 handaxe +14 (1d6+2/x3 plus 1d6 profane) or +1 handaxe +12 (1d6+2/x3 plus 1d6 profane) and mwk handaxe +12 (1d6/x3 plus 1d6 profane)","ranged":"mwk spear +13 (1d8+1/x3 plus 1d6 profane)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"profane attacks"},{"type":"ranger's focus","details":"+4, 3/day"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect good"},{"spell":"detect magic"}]},{"frequency":"2/day","spells":[{"spell":"invisibility"}]}],"spellsprepared_caster":"ranger","spellsprepared_caster_level":4,"spellsprepared_concentration":6,"spellsprepared":[{"spell_level":2,"spell_slots":1,"spells":[{"spell":"protective spirit"}]},{"spell_level":1,"spell_slots":2,"spells":[{"spell":"endure elements"},{"spell":"feather step"}]}],"strength":12,"dexterity":21,"constitution":14,"intelligence":10,"wisdom":14,"charisma":8,"baseatk":7,"cmb":8,"cmd":24,"feats":[{"feat":"Dodge"},{"feat":"Endurance"},{"feat":"Quick Draw"},{"feat":"Toughness"},{"feat":"Two-Weapon Defense"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (handaxe)"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Climb","value":9},{"skill":"Handle Animal","value":9},{"skill":"Intimidate","value":6},{"skill":"Knowledge (geography)","value":5,"special":"+2 in cold"},{"skill":"Knowledge (nature)","value":5},{"skill":"Perception","value":12,"special":"+2 in cold"},{"skill":"Stealth","value":17,"special":"+2 in cold"},{"skill":"Survival","value":12,"special":"+2 in cold"},{"skill":"Swim","value":5}],"languages":["Common","Erutaki"],"sq":["favored terrain (cold +2)","possessed","terrain bond","track +3","wild empathy +6","woodland stride"],"special_abilities":[{"type":"Possessed","kind":"Su","details":"Naquun is possessed by a quasit named Eguriak; the quasit can take no actions other than communicating with its host and using Intelligence-based skills. It can be detected by divinations but cannot be targeted by spell effects (except as described under spell vulnerability below). Damage to Naquun doesn't harm the quasit. If Naquun is killed, Eguriak appears in his square. If the possession is ended without killing Naquun, the hunter's alignment returns to neutral."},{"type":"Profane Attacks","kind":"Su","details":"Naquun's melee attacks deal an extra 1d6 points of damage to creatures of good alignment. In addition, his weapons are treated as evil-aligned and magic for the purpose of overcoming DR."},{"type":"Spell Vulnerability","kind":"Ex","details":"If Naquun is targeted with a banishment or dismissal spell, he must succeed at a Will save or the quasit is banished back to the Abyss. If Naquun is targeted with dispel chaos, dispel evil, protection from chaos, or protection from evil, he must also make a Will save. On a failed save, the quasit is driven out of his body and appears in the nearest open square. It cannot possess a new host."}],"gear":"masterwork studded leather, +1 handaxe, masterwork handaxe, masterwork spear, cold-weather outfit, smoked goggles, snowshoes, trail rations (5 days), 13 gp, campfire beads (3), potions of cure light wounds (2), scroll of campfire wall, scroll of hide campsite, alchemist's fire, tindertwigs (5)","before_combat":"Naquun casts feather step before taking position in front of the door.","during_combat":"Naquun casts protective spirit on the first round of combat. He activates his ranger's focus ability on the first foe to attack, making the majority of his attacks against that opponent. If surrounded by enemies, Naquun casts invisibility to better position himself and attack from surprise.","morale":"As long as he is possessed, Naquun fights to the death. If freed from his possession, he immediately surrenders and offers to help the PCs find Tunuak and bring him to justice.","source":"AP 51, Advanced Bestiary 51, Pathfinder RPG Advanced Player's Guide 125"},{"name":"Frost Phantom","cr":5,"xp":1600,"race":"phantom fungus","age_category":"Adult","alignment":"N","size":"Medium","type":"plant","templates_applied":"advanced","init":6,"senses":["blindsight 30 ft.","low-light vision","tremorsense 60 ft."],"ac":19,"ac_touch":12,"ac_flat_footed":17,"ac_mods":"+2 Dex, +7 natural","hp":52,"hd":"7d8+21","hd_value":7,"fort":8,"ref":4,"will":4,"immunities":["cold","plant traits"],"speed":[{"type":"climb","speed":20},{"type":"land","speed":20}],"melee":"bite +10 (1d6+6 plus 1d6 cold)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"phantom flesh"}],"strength":19,"dexterity":14,"constitution":16,"intelligence":2,"wisdom":15,"charisma":9,"baseatk":5,"cmb":9,"cmd":21,"cmd_special":"23 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Stealth)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Climb","value":12},{"skill":"Perception","value":12},{"skill":"Stealth","value":15}],"special_abilities":[{"type":"Phantom Flesh","kind":"Su","details":"As a move action, a frost phantom can turn invisible as if using greater invisibility (caster level 7th). A moment after it attacks invisibly, the creature appears briefly as a transparent version of its normal self. This allows any viewer with line of sight to the frost phantom to pinpoint its location at the time of the attack (though if the creature moves after it attacks, opponents have to pinpoint it again). An opponent can ready an action to strike at the fungus when it momentarily appears, in which case the creature only has concealment instead of invisibility (20% miss chance). The fungus can turn completely visible as a move action, though it normally remains invisible all the time. If killed while invisible, it becomes visible 1d4 minutes later."}],"source":"AP 51, Pathfinder RPG Bestiary 3 219"},{"name":"Headless Warden","cr":7,"xp":3200,"race":"mummy","age_category":"Adult","alignment":"LE","size":"Medium","type":"undead","templates_applied":"advanced","init":0,"senses":["blindsight 60 ft."],"auras":["despair (30 ft., paralyzed for 1d4 rounds, Will DC 17 negates)"],"ac":22,"ac_touch":10,"ac_flat_footed":22,"ac_mods":"+2 armor, +10 natural","hp":75,"hd":"10d8+30","hd_value":10,"fort":5,"ref":3,"will":9,"defensive_abilities":["spirit wisps"],"dr":"5/-","immunities":["cold","undead traits"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":20}],"melee":"slam +15 (1d8+10 plus mummy rot)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"mummy rot","details":"DC 17"},{"type":"spirit slam +9","details":"1d4+2 negative energy"}],"strength":24,"dexterity":10,"intelligence":6,"wisdom":15,"charisma":15,"baseatk":7,"cmb":14,"cmd":24,"feats":[{"feat":"Light Armor Proficiency"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Perception","value":16},{"skill":"Stealth","value":11}],"languages":["Erutaki"],"special_abilities":[{"type":"Spirit Slam","kind":"Su","details":"Within the Uqtaal Necropolis, a headless warden is surrounded by spirit wisps that harass its foes. These spirits make one slam attack each round against a living foe that is adjacent to the warden, using the warden's full base attack bonus, plus its Charisma modifier. The slam deals 1d4 points of negative energy damage, plus additional negative energy damage equal to the warden's Charisma modifier (+2 in most cases)."},{"type":"Spirit Wisps","kind":"Su","details":"Within the Uqtaal Necropolis, a headless warden is guided and warded by the spirits of the dead that swirl around the warden in pale glowing wisps. These spirits grant the warden blindsight 60 ft. and make it difficult for the warden's enemies to see it. Ranged attacks and melee attacks made by creatures that are not adjacent to the warden (typically because of reach) have a 20% miss chance."}],"gear":"broken chain shirt","during_combat":"The headless wardens make slam attacks at the closest foe. If enemies are near the crevasse, they attempt to bull rush them into it.","morale":"The headless wardens fight until destroyed.","source":"AP 51, Pathfinder RPG Bestiary 210"},{"name":"Yeti Savage","cr":7,"xp":3200,"race":"Yeti","age_category":"Adult","classes":[{"class":"barbarian","level":3,"archetype":"savage barbarian"}],"alignment":"N","size":"Large","type":"monstrous humanoid","sub_types":["cold"],"init":2,"senses":["darkvision 60 ft.","scent"],"ac":18,"ac_touch":10,"ac_flat_footed":15,"ac_mods":"+2 Dex, +1 dodge, +8 natural, -2 rage, -1 size","hp":109,"hd":"6d10+3d12+57","hd_value":9,"fort":11,"ref":8,"will":10,"save_mods":"+1 vs. fear","defensive_abilities":["naked courage","uncanny dodge"],"immunities":["cold"],"weaknesses":["vulnerability to fire"],"speed":[{"type":"climb","speed":30},{"type":"land","speed":50}],"melee":"bite +11 (1d6+4 plus 1d6 cold), 2 claws +16 (1d6+8/19-20 plus 1d6 cold)","ranged":"spear +10 (2d6+8/x3)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"cold"},{"type":"frightful gaze","details":"DC 13"},{"type":"rage","details":"12 rounds/day"},{"type":"rage powers","details":"animal fury"},{"type":"rend","details":"2 claws, 1d6+12 plus 1d6 cold"}],"strength":27,"dexterity":14,"constitution":23,"intelligence":7,"wisdom":14,"charisma":10,"baseatk":9,"cmb":18,"cmb_special":"+22 to drag","cmd":29,"cmd_special":"31 vs. drag","feats":[{"feat":"Cleave"},{"feat":"Greater Drag*"},{"feat":"Improved Critical (claws)"},{"feat":"Improved Drag*"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":20},{"skill":"Perception","value":14},{"skill":"Stealth","value":10,"special":"+8 in snow"},{"skill":"Survival","value":8}],"languages":["Aklo"],"sq":["fast movement"],"gear":"spear, amulet of natural armor +1","during_combat":"The yeti savages rage and attack intruders, often bodily dragging foes up a wall or ceiling or to the edge of a shelf, pit, or crevasse before dropping them.","morale":"While raging, the yeti savages fight to the death. If not raging, a yeti savage flees when reduced to fewer than 30 hit points.","base_statistics":"When not raging, a yeti savage's statistics are AC 20, touch 12, flat-footed 17; hp 91; Fort +9, Will +8; Melee 2 claws +14 (1d6+6/19-20 plus 1d6 cold); Ranged spear +10 (2d6+6/x3); Special Attacks rend (1d6+9 plus 1d6 cold); Str 23, Con 19; CMB +16 (+20 to drag); Skills Climb +18.","source":"AP 51, Pathfinder RPG Bestiary 287, Pathfinder RPG Advanced Player's Guide 79"},{"name":"Katiyana","cr":10,"xp":9600,"race":"sylph","gender":"Female","age_category":"Adult","classes":[{"class":"cleric of Sithhud","level":9}],"alignment":"CE","size":"Medium","type":"outsider","sub_types":["native"],"templates_applied":"half-fiend","init":3,"senses":["darkvision 60 ft."],"ac":27,"ac_touch":16,"ac_flat_footed":24,"ac_mods":"+7 armor, +3 deflection, +3 Dex, +1 natural, +3 shield","hp":93,"hd":"9d8+49","hd_value":9,"fort":8,"ref":8,"will":14,"save_mods":"+1 vs. fear, +4 vs. cold-based attacks","dr":"5/magic","immunities":["poison"],"resists":["acid 10","cold 10","electricity 10","fire 10"],"sr":21,"speed":[{"type":"fly","speed":40,"maneuverability":"good"},{"type":"land","speed":20}],"melee":"bite +7 (1d6), 2 claws +7 (1d4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"8/day, DC 19, 5d6"},{"type":"fury of the Abyss","details":"9/day, +4"},{"type":"gale aura","details":"9 rounds"},{"type":"scythe of evil","details":"4 rounds, 1/day"},{"type":"smite good","details":"1/day, +5 attack and AC, +9 damage"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"desecrate"},{"spell":"feather fall"},{"spell":"unholy blight"}]},{"frequency":"3/day","spells":[{"spell":"darkness"},{"spell":"poison"}]},{"frequency":"9/day","spells":[{"spell":"storm burst","details":"1d6+4 nonlethal damage"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":9,"spellsprepared_concentration":15,"spellsprepared":[{"spell_level":5,"spell_slots":3,"spells":[{"spell":"call lightning storm"},{"spell":"greater command"},{"spell":"summon monster V"}]},{"spell_level":4,"spell_slots":4,"spells":[{"spell":"chaos hammer"},{"spell":"freedom of movement"},{"spell":"sleet storm"},{"spell":"spiritual ally"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"blindness/deafness"},{"spell":"call lightning"},{"spell":"dispel magic"},{"spell":"magic vestment"},{"spell":"protection from energy"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"aid"},{"spell":"cure moderate wounds"},{"spell":"death knell"},{"spell":"fog cloud"},{"spell":"hold person"},{"spell":"silence"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"command"},{"spell":"cure light wounds"},{"spell":"divine favor"},{"spell":"doom"},{"spell":"entropic shield"},{"spell":"protection from law"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"guidance"},{"spell":"read magic"},{"spell":"resistance"}]}],"spelldomains":"Evil, Weather","strength":10,"dexterity":16,"constitution":14,"intelligence":18,"wisdom":22,"charisma":20,"baseatk":6,"cmb":6,"cmd":22,"feats":[{"feat":"Demonic Obedience"},{"feat":"Flyby Attack"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":14},{"skill":"Diplomacy","value":14},{"skill":"Fly","value":10},{"skill":"Knowledge (arcana)","value":14},{"skill":"Knowledge (planes)","value":14},{"skill":"Linguistics","value":10},{"skill":"Perception","value":9},{"skill":"Spellcraft","value":14},{"skill":"Use Magic Device","value":14}],"languages":["Common","Abyssal","Aklo","Aquan","Auran","Dwarven","Elven","Erutaki","Giant"],"sq":["air affinity"],"special_abilities":[{"type":"Demonic Obedience","details":"This feat grants Katiyana a +4 profane bonus on saves against cold-based attacks, as long as she performs a 1-hour daily obedience to Sithhud (Lords of Chaos: Book of the Damned, Vol. 2 8)."}],"gear":"+1 breastplate, masterwork buckler, headband of mental superiority +2 (Use Magic Device), spell component pouch, unholy symbol of Sithhud, scroll of cleanse","before_combat":"Katiyana casts magic vestment on her shield every day. Before combat, she casts aid, call lightning storm, freedom of movement, protection from energy (fire), and shield of faith.","during_combat":"Katiyana uses Flyby Attack to move to the edge of cover and cast spells or unleash called lightning on her enemies before retreating back into hiding. She casts chaos hammer or unholy blight against groups, or greater command to force their obedience to her cruel whims. She casts silence against spellcasters, and casts summon monster V to summon a babau demon to attack melee combatants, along with spiritual ally. If enemies get too close, she activates her gale aura or casts sleet storm to hinder them. If forced into melee combat, Katiyana casts divine favor and activates her fury of the Abyss ability.","morale":"Sure of her success and her demonic patron's favor, Katiyana fights to the death.","base_statistics":"Without her spells, Katiyana's statistics are AC 22, touch 13, flat-footed 19; hp 80; Melee bite +6 (1d6), 2 claws +6 (1d4).","source":"AP 51, Pathfinder RPG Bestiary 171, Pathfinder RPG Bestiary 2 258"},{"name":"Katiyana's Ghost","cr":12,"xp":19200,"race":"sylph","gender":"Female","age_category":"Adult","classes":[{"class":"cleric of Sithhud","level":9}],"alignment":"CE","size":"Medium","type":"undead","sub_types":["augmented outsider","cold","incorporeal"],"templates_applied":"ghost, half-fiend","init":3,"senses":["darkvision 60 ft."],"auras":["blizzard aura"],"ac":21,"ac_touch":21,"ac_flat_footed":18,"ac_mods":"+8 deflection, +3 Dex","hp":134,"hd":"9d8+90","hd_value":9,"fort":14,"ref":8,"will":13,"save_mods":"+4 vs. cold-based attacks","defensive_abilities":["channel resistance +4","incorporeal"],"dr":"5/magic","immunities":["cold","undead traits"],"resists":["acid 10","electricity 10","fire 10"],"sr":23,"weaknesses":["storm-torn","vulnerable to fire"],"speed":[{"type":"fly","speed":60,"maneuverability":"perfect"}],"melee":"corrupting touch +9 (12d6, Fort DC 22 half)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"11/day, DC 22, 5d6"},{"type":"corrupting touch"},{"type":"fury of the Abyss","details":"8/day, +4"},{"type":"gale aura"},{"type":"icy heart"},{"type":"malevolence","details":"Will DC 22"},{"type":"scythe of evil","details":"4 rounds, 1/day"},{"type":"smite good","details":"1/day, +8 attack and AC, +8 damage"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"desecrate"},{"spell":"feather fall"},{"spell":"unholy blight"}]},{"frequency":"3/day","spells":[{"spell":"darkness"},{"spell":"poison"}]},{"frequency":"8/day","spells":[{"spell":"storm burst","details":"1d6+4 nonlethal damage"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":9,"spellsprepared_concentration":14,"spellsprepared":[{"spell_level":5,"spell_slots":3,"spells":[{"spell":"call lightning storm"},{"spell":"greater command"},{"spell":"summon monster V"}]},{"spell_level":4,"spell_slots":4,"spells":[{"spell":"blessing of fervor"},{"spell":"divine power"},{"spell":"sleet storm"},{"spell":"spell immunity"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"call lightning"},{"spell":"dispel magic"},{"spell":"invisibility purge"},{"spell":"meld into stone"},{"spell":"protection from energy"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"bear's endurance"},{"spell":"bull's strength"},{"spell":"eagle's splendor"},{"spell":"fog cloud"},{"spell":"hold person"},{"spell":"silence"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"command"},{"spell":"divine favor"},{"spell":"entropic shield"},{"spell":"obscuring mist"},{"spell":"protection from good"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"guidance"},{"spell":"read magic"},{"spell":"stabilize"}]}],"spelldomains":"Evil, Weather","dexterity":16,"intelligence":16,"wisdom":20,"charisma":26,"baseatk":6,"cmb":9,"cmd":27,"feats":[{"feat":"Demonic Obedience"},{"feat":"Flyby Attack"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":17},{"skill":"Diplomacy","value":17},{"skill":"Fly","value":17},{"skill":"Knowledge (arcana)","value":13},{"skill":"Knowledge (planes)","value":13},{"skill":"Linguistics","value":9},{"skill":"Perception","value":16},{"skill":"Spellcraft","value":13},{"skill":"Stealth","value":11}],"languages":["Common","Abyssal","Aklo","Aquan","Auran","Dwarven","Elven","Erutaki"],"sq":["air affinity"],"special_abilities":[{"type":"Blizzard Aura","kind":"Su","details":"Katiyana has become one with the morozko. Her gale aura functions continuously, and any creature beginning its turn inside the aura is buffeted with howling wind and driving snow, causing it to take a -2 penalty on attack rolls for 1 round. Katiyana's blizzard aura doesn't function when she uses malevolence to possess another creature. Dispel magic or control winds suppresses the blizzard aura with a DC 20 caster level check for 1 round per level of the caster."},{"type":"Icy Heart","kind":"Su","details":"A heart of ice, pulsing with midnight blue radiance, beats within Katiyana's ghostly form, serving as her divine focus and granting her the cold subtype. In addition, whenever she deals cold damage to a creature with resistance to cold, half of the cold damage penetrates that resistance; the remaining damage is blocked normally. Creatures with immunity to cold are unaffected."},{"type":"Storm-Torn","kind":"Su","details":"Katiyana became a ghost when the Storm Sphere scattered her spirit on the polar winds. As a result, Katiyana doesn't have a normal ghost's rejuvenation ability, and is permanently destroyed when her hit points reach 0."}],"before_combat":"Katiyana retains the spell effects she cast while possessing Bormurg. In addition, any other spells that she cast while possessing Bormurg are no longer prepared.","during_combat":"Katiyana summons a Large air, ice, or lightning elemental or fiendish woolly rhinoceros on the first round of combat to attack her enemies. She uses Flyby Attack to move in and out of cover or concealment, using spells or called lightning against her enemies.","morale":"Although unable to rejuvenate, Katiyana's fury overwhelms her and she fights until destroyed.","base_statistics":"Without eagle's splendor, Katiyana's statistics are AC 19, touch 19, flat-footed 16; hp 116; Fort +12; Cha 22; CMD 25; Skills Bluff +15, Diplomacy +15; reduce all save DCs by 2.","source":"AP 51, Pathfinder RPG Bestiary 144, 171; Bestiary 2 258"},{"name":"Bormurg (possessed)","xp":0,"race":"ghost-possessed yeti","gender":"Male","age_category":"Adult","classes":[{"class":"ranger","level":5}],"alignment":"CE","size":"Large","type":"monstrous humanoid","sub_types":["cold"],"init":2,"senses":["darkvision 60 ft.","scent"],"ac":25,"ac_touch":14,"ac_flat_footed":23,"ac_mods":"+4 armor, +3 deflection, +2 Dex, +7 natural, -1 size","hp":142,"hd":"11d10+82","hd_value":11,"fort":14,"ref":12,"will":18,"immunities":["cold"],"weaknesses":["vulnerability to fire"],"speed":[{"type":"climb","speed":30},{"type":"land","speed":40}],"melee":"2 claws +14 (1d6+9 plus 1d6 cold)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"cold"},{"type":"frightful gaze","details":"DC 21"},{"type":"rend","details":"2 claws, 1d6+13 plus 1d6 cold"},{"type":"spellcasting"}],"strength":28,"dexterity":14,"constitution":23,"intelligence":16,"wisdom":20,"charisma":26,"baseatk":6,"cmb":16,"cmd":31,"feats":[{"feat":"Alertness"},{"feat":"Demonic Obedience"},{"feat":"Flyby Attack"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":17},{"skill":"Climb","value":17},{"skill":"Diplomacy","value":17},{"skill":"Fly","value":6},{"skill":"Knowledge (arcana)","value":13},{"skill":"Knowledge (planes)","value":13},{"skill":"Linguistics","value":9},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":7},{"skill":"Spellcraft","value":13},{"skill":"Stealth","value":2,"special":"+8 in snow"}],"languages":["Common","Abyssal","Aklo","Aquan","Auran","Dwarven","Elven","Erutaki"],"special_abilities":[{"type":"Spellcasting","kind":"Su","details":"While possessing Bormurg's body, Katiyana has access to all of her spells, spell-like abilities, granted powers, and special attacks, except her corrupting touch."}],"gear":"+1 studded leather, dark blue rhomboid ioun stone","before_combat":"Katiyana casts bear's endurance, bull's strength, call lightning storm, eagle's splendor, entropic shield, protection from energy (fire), shield of faith, and spell immunity (to magic missile and spiritual weapon) before entering combat. She uses meld into stone to hide on the ledge above area S16 until alerted by Bormurg's consorts to the party's approach.","during_combat":"When the yetis attack begins, Katiyana casts divine power while melded into the stone. On the following round, she steps out of the stone and casts blessing of fervor on herself and her allies. She wades into melee, using her fury of the Abyss domain power every round (gaining a +4 bonus on attacks, damage rolls, and combat maneuver checks, and taking a -2 penalty to AC).","morale":"Katiyana fights in Bormurg's body until he dies or she is expelled, then fights on in her ghost form until destroyed.","base_statistics":"Without Katiyana's spells, Bormurg's statistics are AC 22, touch 11, flat-footed 20; hp 120; Fort +12; Melee 2 claws +12 (1d6+7 plus 1d6 cold); Special Attacks rend (2 claws, 1d6+10 plus 1d6 cold); Str 24, Con 19, Cha 22; CMB +14; CMD 26; Skills Bluff +15, Climb +15, Diplomacy +1.","source":"AP 51, Pathfinder RPG Bestiary 287"},{"name":"Tunuak","cr":8,"xp":4800,"race":"human","gender":"Male","age_category":"Old","classes":[{"class":"oracle","level":9}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["human"],"init":0,"ac":21,"ac_touch":13,"ac_flat_footed":21,"ac_mods":"+6 armor, +3 deflection, +2 natural","hp":80,"hd":"9d8+36","hd_value":9,"fort":8,"ref":5,"will":11,"speed":[{"type":"land","speed":30}],"melee":"staff of journeys +3 (1d6-3)","space":"5 ft.","reach":"5 ft.","spellsknown_caster":"oracle","spellsknown_caster_level":9,"spellsknown_concentration":16,"spellsknown":[{"spell_level":4,"spell_slots":5,"spells":[{"spell":"cure critical wounds"},{"spell":"river of wind"},{"spell":"spiritual ally"},{"spell":"unholy blight"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"borrow fortune"},{"spell":"cloak of winds"},{"spell":"cure serious wounds"},{"spell":"dispel magic"},{"spell":"protection from energy"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"bear's endurance"},{"spell":"cure moderate wounds"},{"spell":"eagle's splendor"},{"spell":"gust of wind"},{"spell":"silence"},{"spell":"spiritual weapon"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"alter winds"},{"spell":"cure light wounds"},{"spell":"divine favor"},{"spell":"doom"},{"spell":"endure elements"},{"spell":"obscuring mist"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"create water"},{"spell":"detect magic"},{"spell":"guidance"},{"spell":"light"},{"spell":"purify food and drink"},{"spell":"read magic"},{"spell":"resistance"},{"spell":"stabilize"}]}],"mystery":"wind","strength":5,"dexterity":10,"constitution":16,"intelligence":14,"wisdom":12,"charisma":24,"baseatk":6,"cmb":3,"cmd":19,"feats":[{"feat":"Combat Expertise"},{"feat":"Defensive Combat Training"},{"feat":"Eschew Materials"},{"feat":"Extra Revelation*"},{"feat":"Iron Will"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":14},{"skill":"Diplomacy","value":19},{"skill":"Fly","value":10},{"skill":"Intimidate","value":12},{"skill":"Knowledge (history)","value":10},{"skill":"Knowledge (planes)","value":6},{"skill":"Knowledge (religion)","value":14},{"skill":"Perception","value":5},{"skill":"Sense Motive","value":13},{"skill":"Spellcraft","value":14},{"skill":"Stealth","value":10}],"languages":["Common","Abyssal","Auran","Draconic","Erutaki","Giant"],"sq":["oracle's curse (tongues; Abyssal, Auran)","revelations (air barrier, invisibility, wind sight, wings of air)"],"gear":"cloak of resistance +2, ring of mind shielding, staff of journeys, cold-weather outfit, unholy symbol of Sithhud, potions of barkskin (2)","before_combat":"Tunuak casts endure elements every day. Before combat, he activates his air barrier and wings of air revelations; drinks a potion of barkskin; and casts bear's endurance, cloak of winds, shield of faith, and protection from energy (against a type commonly used by the PCs, likely fire). Before he makes his pronouncement against the PCs, Tunuak casts eagle's splendor.","during_combat":"Tunuak activates his invisibility revelation to gain greater invisibility and casts attack spells such as unholy blight and silence. He creates spiritual allies adjacent to spellcasters and multiple spiritual weapons (appearing as longswords, Sithhud's favored weapon). If several opponents are in a line, he casts river of wind against them.","morale":"If reduced to fewer than 20 hit points or if all of his minions are slain, Tunuak uses his invisibility revelation to flee Iqaliat entirely and harry the PCs' caravan on their further journeys. If confronted by the PCs before they venture into Tunuak's Bore, Tunuak uses his invisibility revelation or casts obscuring mist and flees to area K3 to set up an ambush with the hoarfrost spirits there.","base_statistics":"Without his spells and revelations, Tunuak's statistics are AC 10, touch 10, flat-footed 10; hp 62; Fort +6; Spells concentration +14, reduce all save DCs by 2; Con 12, Cha 20; CMD 16; Skills Bluff +12, Diplomacy +17, Intimidate +10.","source":"AP 51, Pathfinder RPG Advanced Player's Guide 42"},{"name":"Vegsundvaag","cr":9,"xp":6400,"race":"young Adult white dragon","gender":"Female","age_category":"Adult","alignment":"CE","size":"Large","type":"dragon","sub_types":["cold"],"init":5,"senses":["dragon senses","snow vision"],"ac":24,"ac_touch":10,"ac_flat_footed":23,"ac_mods":"+1 Dex, +14 natural, -1 size","hp":115,"hd":"11d12+44","hd_value":11,"fort":11,"ref":8,"will":8,"dr":"5/magic","immunities":["cold","magic paralysis and sleep"],"sr":20,"weaknesses":["vulnerable to fire"],"speed":[{"type":"burrow","speed":30},{"type":"fly","speed":200,"maneuverability":"poor"},{"type":"land","speed":60},{"type":"swim","speed":60}],"melee":"bite +17 (2d6+9/19-20), 2 claws +16 (1d8+6), tail slap +14 (1d8+3), 2 wings +14 (1d6+3)","space":"10 ft.","reach":"5 ft. (10 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"40-ft. cone, 10d4 cold damage, Reflex DC 19 half, usable every 1d4 rounds"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":11,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"fog cloud"},{"spell":"gust of wind"}]}],"strength":23,"dexterity":12,"constitution":19,"intelligence":10,"wisdom":13,"charisma":10,"baseatk":11,"cmb":18,"cmd":29,"cmd_special":"33 vs. trip","feats":[{"feat":"Flyby Attack"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Climb","value":15},{"skill":"Fly","value":9},{"skill":"Knowledge (geography)","value":14},{"skill":"Knowledge (local)","value":10},{"skill":"Linguistics","value":6},{"skill":"Perception","value":15},{"skill":"Stealth","value":11},{"skill":"Survival","value":10},{"skill":"Swim","value":14}],"languages":["Common","Draconic","Erutaki","Giant"],"sq":["ice shape","icewalking"],"during_combat":"Vegsundvaag prefers to cover her approach with multiple fog clouds, or to burrow close to her prey before bursting out of the ice. She avoids directly engaging groups that might surround her, but targets them with her breath weapon, and makes Flyby Attacks at isolated foes. Vegsundvaag typically reserves full attacks for enemies challenging her in the air, but foes who separate themselves from their allies also invite her to swoop close to bite with her great reach, then drop to the ground for a full attack on the following round.","morale":"If reduced to fewer than 30 hit points, Vegsundvaag attempts to flee, using fog cloud to cover her escape via flight or burrowing into the ice, but she may return later to wreak vengeance on her attackers.","source":"AP 51, Pathfinder RPG Bestiary 100"},{"name":"Five Storms Ninja","cr":6,"xp":2400,"race":"human","age_category":"Adult","classes":[{"class":"ninja","level":7}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["human"],"init":8,"ac":19,"ac_touch":15,"ac_flat_footed":14,"ac_mods":"+4 armor, +4 Dex, +1 dodge","hp":56,"hd":"7d8+21","hd_value":7,"fort":6,"ref":9,"will":3,"defensive_abilities":["uncanny dodge"],"speed":[{"type":"land","speed":30}],"melee":"mwk katana* +11 (1d8+1 plus poison/18-20)","ranged":"shuriken +9 (1d2+1 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+4d6"}],"strength":12,"dexterity":18,"constitution":14,"intelligence":10,"wisdom":8,"charisma":13,"baseatk":5,"cmb":6,"cmd":21,"feats":[{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (katana*)"}],"skills":[{"skill":"Acrobatics","value":13},{"skill":"Bluff","value":11},{"skill":"Climb","value":10},{"skill":"Disguise","value":11},{"skill":"Escape Artist","value":13},{"skill":"Intimidate","value":8},{"skill":"Perception","value":9},{"skill":"Sleight of Hand","value":14},{"skill":"Stealth","value":13},{"skill":"Swim","value":6}],"languages":["Tien (cannot speak)"],"sq":["ki pool (4)","light steps","ninja tricks (fast stealth, finesse rogue, smoke bomb)","no trace +2","poison use"],"special_abilities":[{"type":"Fast Stealth","kind":"Ex","details":"The ninja can move at full speed using the Stealth skill without penalty."},{"type":"Ki Pool","kind":"Su","details":"A ninja has a pool of ki points, supernatural energy she can use to accomplish amazing feats. As long as she has at least 1 point in her ki pool, a ninja treats any Acrobatics skill check made to jump as if she had a running start. By spending 1 point from her ki pool, a ninja can make one additional attack at her highest attack bonus, but she can do so only when making a full attack. In addition, she can spend 1 point to increase her speed by 20 ft. for 1 round. Finally, a ninja can spend 1 point from her ki pool to give herself a +4 insight bonus on Stealth skill checks for 1 round. Each of these powers is activated as a swift action."},{"type":"Light Steps","kind":"Ex","details":"As a full-round action, a ninja can move up to twice her speed, ignoring difficult terrain. While moving in this way, any surface will support her, no matter how much she weighs. This allows her to move across water, lava, or even the thinnest tree branches. She must end her move on a surface that can support her normally. She cannot move across air in this way, nor can she walk up walls or other vertical surfaces. When moving in this way, she doesn't take damage from surfaces or hazards that react to being touched, such as lava or caltrops, nor does she need to make Acrobatics checks to avoid falling on slippery or rough surfaces. Finally, when using light steps, the ninja ignores any mechanical traps that use a location-based trigger."},{"type":"No Trace","kind":"Ex","details":"A ninja learns to cover her tracks, remain hidden, and conceal her presence. The DC to track a ninja using the Survival skill increases by +2. In addition, her training gives her a +2 insight bonus on Disguise skill checks and on opposed Stealth checks whenever she is stationary and doesn't take any action for at least 1 round."},{"type":"Poison Use","kind":"Ex","details":"A ninja is trained in the use of poison and cannot accidentally poison herself when applying poison to a weapon."},{"type":"Smoke Bomb","kind":"Ex","details":"As a standard action, a ninja can throw a smoke bomb that creates a cloud of smoke with a 15-foot radius. This acts like the smoke from a smokestick. The ninja can center this smoke on herself, or throw the bomb as a ranged touch attack with a range of 20 feet. Each use of this ability uses up 1 ki point."}],"gear":"masterwork chain shirt, masterwork katana, shuriken (12), potion of cure serious wounds, potion of displacement, shadow essence (6 doses)","before_combat":"The ninja poison their katanas and shuriken with shadow essence before combat, and drink their potions of displacement.","during_combat":"The ninja pair up against opponents, flanking to make sneak attacks.","morale":"If reduced to 20 hit points or fewer, the ninja drink their potions of cure serious wounds. If reduced to 8 hit points or fewer after this point, the ninja commit seppuku (ritual suicide by performing a self-inflicted coup de grace with their katanas) rather than submit to capture.","source":"AP 52, Pathfinder RPG Ultimate Combat 13"},{"name":"Giant Sapphire Spider","cr":3,"xp":800,"race":"giant spider","age_category":"Adult","alignment":"N","size":"Medium","type":"vermin","templates_applied":"advanced","init":5,"senses":["darkvision 60 ft.","tremorsense 60 ft."],"ac":16,"ac_touch":15,"ac_flat_footed":11,"ac_mods":"+5 Dex, +1 natural","hp":32,"hd":"5d8+10","hd_value":5,"fort":6,"ref":6,"will":2,"immunities":["mind-affecting effects"],"speed":[{"type":"climb","speed":30},{"type":"land","speed":30}],"melee":"bite +5 (1d6+3 plus poison)","space":"5 ft.","reach":"5 ft.","strength":15,"dexterity":21,"constitution":14,"wisdom":12,"charisma":2,"baseatk":3,"cmb":5,"cmd":20,"cmd_special":"32 vs. trip","skills":[{"skill":"Acrobatics","value":13},{"skill":"Climb","value":18},{"skill":"Perception","value":5},{"skill":"Stealth","value":9,"special":"+4 in webs"}],"special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 16; frequency 1/round for 6 rounds; effect 1d3 Str damage; cure 2 consecutive saves."}],"source":"AP 52, Pathfinder RPG Bestiary 258"},{"name":"The Gossamer","cr":8,"xp":4800,"race":"aranea","gender":"Female","age_category":"Adult","classes":[{"class":"shadowdancer","level":4}],"alignment":"LE","size":"Medium","type":"magical beast","sub_types":["shapechanger"],"init":9,"senses":["darkvision 90 ft.","low-light vision"],"ac":23,"ac_touch":16,"ac_flat_footed":17,"ac_mods":"+4 armor, +5 Dex, +1 dodge, +3 natural","hp":75,"hd":"5d10+4d8+32","hd_value":9,"fort":9,"ref":11,"will":1,"defensive_abilities":["evasion","uncanny dodge"],"weaknesses":["opium addict"],"speed":[{"type":"land","speed":30,"special":"cannot run or charge"}],"melee":"mwk dagger +14 (1d4+1/19-20 plus aranea poison [DC 14])","ranged":"mwk dagger +14 (1d4+1/19-20 plus aranea poison [DC 14])","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"web","details":"+13 ranged, DC 16, 5 hp"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"shadow call"}]},{"frequency":"2/day","spells":[{"spell":"shadow illusion"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":5,"spellsknown_concentration":9,"spellsknown":[{"spell_level":2,"spell_slots":5,"spells":[{"spell":"false life"},{"spell":"mirror image"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"charm person"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"vanish"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"message"},{"spell":"resistance"},{"spell":"touch of fatigue"}]}],"strength":12,"dexterity":20,"constitution":16,"intelligence":14,"wisdom":10,"charisma":19,"baseatk":8,"cmb":9,"cmd":25,"feats":[{"feat":"Ability Focus (web)"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Eschew Materials","type":"bonus"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":16},{"skill":"Bluff","value":11},{"skill":"Climb","value":8},{"skill":"Escape Artist","value":12},{"skill":"Knowledge (arcana)","value":6},{"skill":"Perception","value":10},{"skill":"Perform (dance)","value":15},{"skill":"Sleight of Hand","value":12},{"skill":"Stealth","value":16}],"languages":["Common","Minkaian","Sylvan","Tien"],"sq":["change shape (humanoid; alter self )","hide in plain sight","rogue talent (finesse rogue)","shadow jump (40 feet/day)","summon shadow"],"special_abilities":[{"type":"Opium Addict","kind":"Ex","details":"The Gossamer are addicted to opium. While under the effects of the drug, they gain +1d8 temporary hit points and a +2 alchemical bonus on Fortitude saves for 1 hour, but they are also fatigued. In addition, they have taken 2 points of Constitution damage and 2 points of Wisdom damage from the drug (already reflected in the stat block)."}],"gear":"masterwork daggers (8), black porcelain mask, black silk kimono embroidered with dark draconic figures (worth 75 gp), necklace of Akinosa's hair, potion of blur, potion of cure serious wounds","before_combat":"The Gossamer cast false life and mage armor before combat, and poison their daggers with their own poison.","during_combat":"The Gossamer initially use their shadow call abilities to summon 1d3 shadowy giant spiders to attack enemies, hoping to draw their opponents' attention while they try to outflank them. The Gossamer use their shadowdancer abilities and spells such as mirror image and vanish to confuse their enemies, always attempting to flank their enemies with each other or their shadow companions. They reserve their shadow jump abilities to escape if they are cornered.","morale":"The Gossamer fight to the death to protect their lover and master Akinosa.","source":"AP 52, Pathfinder RPG Bestiary 2 30"},{"name":"Shadow Companion","xp":0,"race":"shadow","gender":"Female","age_category":"Adult","alignment":"LE","size":"Medium","type":"undead","sub_types":["incorporeal"],"init":2,"senses":["darkvision 60 ft."],"ac":15,"ac_touch":15,"ac_flat_footed":12,"ac_mods":"+2 deflection, +2 Dex, +1 dodge","hp":35,"hd":"3d8+6","hd_value":3,"fort":7,"ref":8,"will":3,"defensive_abilities":["cannot be turned or commanded","channel resistance +4","incorporeal"],"immunities":["undead traits"],"speed":[{"type":"fly","speed":40,"maneuverability":"good"}],"melee":"incorporeal touch +10 (1d6 Strength damage)","space":"5 ft.","reach":"5 ft.","dexterity":14,"intelligence":6,"wisdom":12,"charisma":15,"baseatk":8,"cmb":10,"cmd":23,"feats":[{"feat":"Dodge"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Fly","value":11},{"skill":"Perception","value":8},{"skill":"Stealth","value":8,"special":"+4 in dim light, -4 in bright light"}],"source":"AP 52, Pathfinder RPG Bestiary 245"},{"name":"Withered Blossom Warrior","cr":7,"xp":3200,"race":"Hobgoblin","age_category":"Adult","classes":[{"class":"fighter","level":5},{"class":"rogue","level":3}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["goblinoid"],"init":7,"senses":["darkvision 60 ft."],"ac":20,"ac_touch":13,"ac_flat_footed":17,"ac_mods":"+5 armor, +3 Dex, +2 shield","hp":82,"hd":"5d10+3d8+37","hd_value":8,"fort":10,"ref":7,"will":2,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1","evasion","trap sense +1"],"speed":[{"type":"land","speed":30}],"melee":"mwk morningstar +13 (1d8+6)","ranged":"mwk composite longbow +11 (1d8+3/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"},{"type":"weapon training","details":"flails +1"}],"strength":16,"dexterity":16,"constitution":16,"intelligence":12,"wisdom":10,"charisma":8,"baseatk":7,"cmb":10,"cmd":23,"feats":[{"feat":"Cleave"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Weapon Focus (morningstar)"},{"feat":"Weapon Specialization (morningstar)"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Climb","value":11},{"skill":"Intimidate","value":10},{"skill":"Knowledge (dungeoneering)","value":6},{"skill":"Perception","value":11},{"skill":"Stealth","value":15}],"languages":["Common","Goblin","Tien"],"sq":["armor training 1","trapfinding +1"],"gear":"masterwork do-maru, masterwork heavy wooden shield, masterwork composite longbow with 20 arrows, masterwork morningstar, potion of cure serious wounds","during_combat":"The hobgoblins on watch fire arrows at intruders until the intruders reach the wall, at which point they attempt to pour boiling oil on the attackers. The warriors are well organized and fight as a unit once their defenses are breached, flanking with one another to make sneak attacks when possible. In combat, the hobgoblins attack araneas and elves in preference to other creatures.","morale":"The hobgoblins worship and fear Munasukaru, and they fight to the death, knowing that if they flee, their treatment at her hands will be unimaginably brutal.","source":"AP 52, Pathfinder RPG Bestiary 175"},{"name":"Buto Futotsu, the Swine Shogun","cr":10,"xp":9600,"race":"hobgoblin","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":11}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["goblinoid"],"init":7,"senses":["darkvision 60 ft."],"ac":24,"ac_touch":14,"ac_flat_footed":21,"ac_mods":"+10 armor, +3 Dex, +1 luck","hp":120,"hd":"11d10+55","hd_value":11,"fort":13,"ref":7,"will":5,"save_mods":"+3 vs. fear","defensive_abilities":["bravery +3"],"speed":[{"type":"land","speed":30}],"melee":"+1 thundering greataxe +21 (1d12+12/19-20/x3)","ranged":"mwk composite longbow +16 (1d8+4/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"weapon training","details":"axes +2, bows +1"}],"strength":20,"dexterity":16,"constitution":16,"intelligence":10,"wisdom":8,"charisma":12,"baseatk":11,"cmb":16,"cmd":29,"feats":[{"feat":"Dazzling Display"},{"feat":"Great Fortitude"},{"feat":"Greater Weapon Focus (greataxe)"},{"feat":"Improved Critical (greataxe)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Mounted Combat"},{"feat":"Ride-By Attack"},{"feat":"Shatter Defenses"},{"feat":"Toughness"},{"feat":"Weapon Focus (greataxe)"},{"feat":"Weapon Specialization (greataxe)"}],"skills":[{"skill":"Handle Animal","value":6},{"skill":"Intimidate","value":15},{"skill":"Perception","value":2},{"skill":"Ride","value":10},{"skill":"Stealth","value":5}],"languages":["Goblin","Tien"],"sq":["armor training 3"],"gear":"+2 o-yoroi, +1 thundering greataxe, dagger with gold hilt (worth 400 gp), masterwork composite longbow (+4 Str) with 20 arrows, belt of giant strength +4, cloak of resistance +1 (made from the skins of 47 piglets), jingasa of the fortunate soldier, bronze rice bowl worth 15 gp, carved horn box with 6 spinels worth 100 gp each, horn libation cup worth 75 gp, 22 gp, potion of cure serious wounds","during_combat":"Buto assumes that Munasukaru is watching him, so he tends to be flashy in combat, using his Dazzling  Display feat before entering combat or when there is a lull in the fighting.","morale":"Buto drinks his potion of cure serious wounds when reduced to fewer than 30 hit points, but if he then reaches 10 hit points or fewer, the Swine Shogun screams an oath to Munasukaru's glory and commits seppuku (ritual suicide by performing a self-inflicted coup de grace with his dagger).","source":"AP 52, Pathfinder RPG Bestiary 175"},{"name":"Sister of the Broken Path","cr":8,"xp":4800,"race":"hobgoblin","gender":"Female","age_category":"Adult","classes":[{"class":"monk","level":9,"archetype":"hungry ghost monk"}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["goblinoid"],"init":7,"senses":["darkvision 60 ft."],"ac":21,"ac_touch":18,"ac_flat_footed":17,"ac_mods":"+2 armor, +3 Dex, +1 dodge, +2 monk, +2 Wis, +1 natural","hp":80,"hd":"9d8+36","hd_value":9,"fort":8,"ref":11,"will":8,"save_mods":"+2 vs. enchantment","defensive_abilities":["improved evasion"],"speed":[{"type":"land","speed":60}],"melee":"mwk nunchaku +10 (1d6+3) or unarmed strike +9 (1d10+3) or mwk nunchaku flurry of blows +11 (1d6+3) or unarmed strike flurry of blows +10 (1d10+3)","ranged":"dagger +9 (1d4+3/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"flurry of blows"},{"type":"life funnel"},{"type":"punishing kick","details":"9/day, DC 16"},{"type":"steal ki"}],"strength":16,"dexterity":16,"constitution":14,"intelligence":10,"wisdom":14,"charisma":8,"baseatk":6,"cmb":12,"cmd":27,"feats":[{"feat":"Combat Reflexes"},{"feat":"Deflect Arrows"},{"feat":"Dodge"},{"feat":"Improved Disarm"},{"feat":"Improved Initiative"},{"feat":"Improved Unarmed Strike"},{"feat":"Lightning Reflexes"},{"feat":"Punishing Kick*"},{"feat":"Skill Focus (Acrobatics)"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":18,"special":"+21 jump"},{"skill":"Climb","value":15},{"skill":"Intimidate","value":10},{"skill":"Perception","value":14},{"skill":"Stealth","value":11}],"languages":["Goblin","Tien"],"sq":["fast movement","high jump","ki pool (6 points, magic)","maneuver training","slow fall 40 ft.","still mind"],"gear":"daggers (4), masterwork nunchaku, amulet of natural armor +1, bracers of armor +2, 100 gp worth of jeweled studs for piercings, potion of blur","before_combat":"The Sisters drink their potions of blur before combat ensues.","during_combat":"The monks work together, attacking as a single group flanking one or two opponents if the opportunity presents itself. They attempt to push enemies into the pit in area C9 using their Punishing Kick feat, or make flurry of blows attacks, using their nunchaku to disarm opponents. If fighting on the Lattice (area C9), the monks use their superior acrobatics skills to maneuver around and outflank foes. The Sisters think nothing of leaping the 10 ft. between the iron bars.","morale":"Devoted followers of Munasukaru, the Sisters of the Broken Path don't surrender, defending their living god to the death. When a monk reaches 10 hit points or fewer, she screams an oath to Munasukaru's glory and commits seppuku (ritual suicide by performing a self-inflicted coup de grace with her dagger).","source":"AP 52, Pathfinder RPG Bestiary 175, Pathfinder RPG Advanced Player's Guide 110"},{"name":"Ichirou, Spawn of Munasukaru","cr":9,"xp":6400,"race":"ja noi","gender":"Male","age_category":"Adult","classes":[{"class":"barbarian","level":4,"archetype":"scarred rager"}],"alignment":"LE","size":"Medium","type":"outsider","sub_types":["goblinoid","native","oni","shapechanger"],"init":4,"senses":["darkvision 60 ft."],"ac":23,"ac_touch":14,"ac_flat_footed":18,"ac_mods":"+5 armor, +1 deflection, +4 Dex, +1 dodge, +4 natural, -2 rage","hp":123,"hd":"6d10+4d12+64","hd_value":10,"hp_mods":"regeneration 3 (acid or fire)","fort":15,"ref":10,"will":7,"defensive_abilities":["scarification","tolerance*"],"speed":[{"type":"fly","speed":60,"maneuverability":"good"},{"type":"land","speed":30}],"melee":"+1 nodachi* +21 (1d10+16/18-20)","ranged":"mwk composite longbow +15 (1d8+6/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rage","details":"14 rounds/day"},{"type":"rage powers","details":"auspicious mark, roused anger"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"bull's strength"}]},{"frequency":"3/day","spells":[{"spell":"command"},{"spell":"doom"},{"spell":"fly"},{"spell":"magic weapon"}]}],"strength":30,"dexterity":18,"constitution":22,"intelligence":10,"wisdom":14,"charisma":19,"baseatk":10,"cmb":20,"cmb_special":"+24 bull rush","cmd":34,"cmd_special":"36 vs. bull rush","feats":[{"feat":"Cleave"},{"feat":"Dodge"},{"feat":"Greater Bull Rush"},{"feat":"Improved Bull Rush"},{"feat":"Power Attack"}],"skills":[{"skill":"Acrobatics","value":17},{"skill":"Bluff","value":15},{"skill":"Climb","value":18},{"skill":"Fly","value":16},{"skill":"Intimidate","value":17,"special":"+2 vs. non-barbarians"},{"skill":"Perception","value":9},{"skill":"Stealth","value":17}],"languages":["Goblin","Tien"],"sq":["change shape (Small or Medium humanoid; alter self )","serene fighter","terrifying visage*"],"special_abilities":[{"type":"Auspicious Mark","kind":"Su","details":"Ichirou's impressive scars and tattoos mark him as touched by the spirits. Once per rage, as a swift action that costs 2 rounds of rage, Ichirou can call upon the spirits' favor, granting him a +1d6 bonus on one d20 roll he has just made. Ichirou can call on the auspicious mark after seeing the result of the d20 roll."},{"type":"Scarification","kind":"Ex","details":"Ichirou can ignore 1 point of bleed damage per round."},{"type":"Terrifying Visage","kind":"Ex","details":"Ichirou adds 1/2 his barbarian level (+2) on Intimidate checks against humanoids who are not members of barbarian tribes. When dealing with barbarians, Ichirou may add this bonus on Diplomacy checks instead. The DC of any fear effect created by Ichirou also increases by +1."},{"type":"Tolerance","kind":"Ex","details":"If Ichirou fails a save against an effect that causes him to become nauseated, sickened, fatigued, or exhausted, he can make a second save to negate the effect on the start of his next turn. Only one additional save is allowed. If the effect doesn't allow a saving throw, its duration is halved instead (minimum of 1 round)."}],"gear":"+2 studded leather, masterwork composite longbow (+6 Str) with 20 arrows, masterwork nodachi, ring of protection +1","before_combat":"Ichirou has little interest in helping the monks defend this area, but he casts bull's strength, fly, and magic weapon if alerted to the presence of intruders.","during_combat":"Ichirou orders the two Sisters of the Broken Path to engage opponents while he remains in the rear watching the fray and using his spell-like abilities. If enemies get past the monks, Ichirou rages and attempts to bull rush foes into the pit in area C9.","morale":"A lustful coward, Ichirou withdraws from combat once he is reduced to 60 hit points or fewer. He attempts to bargain for his life with information, preferably with an attractive female. Ichirou knows the general layout of the Penance, although not many specifics (he's far more interested in sating his lusts than paying attention to such mundane matters as personnel and staffing). If his parlay is refused, Ichirou rages once more and fights to the death.","source":"AP 52, Pathfinder RPG Ultimate Combat 29"}];
